import { Cascader, type CascaderValueDetail } from '@absoluteui/components/cascader';

const host = document.createElement('div');
const summary = document.createElement('p');
document.body.append(host, summary);
Cascader.create(host, {
  label: 'Work location',
  name: 'city',
  required: true,
  levelLabels: ['Country', 'State', 'City'],
  options: [
    { value: 'in', label: 'India', children: [
      { value: 'ka', label: 'Karnataka', children: [{ value: 'blr', label: 'Bengaluru' }, { value: 'mys', label: 'Mysuru' }] },
      { value: 'kl', label: 'Kerala', children: [{ value: 'cok', label: 'Kochi' }] },
    ] },
    { value: 'de', label: 'Germany', children: [
      { value: 'be', label: 'Berlin', children: [{ value: 'ber', label: 'Berlin' }] },
    ] },
  ],
  value: ['in', 'ka', 'blr'],
});
host.addEventListener('aui-change', (event) => {
  const { labels } = (event as CustomEvent<CascaderValueDetail>).detail;
  summary.textContent = Array.isArray(labels) ? labels.join(' > ') : 'No location';
});

import { Cascader, type CascaderOption } from '@absoluteui/components/cascader';

const host = document.createElement('div');
document.body.append(host);
Cascader.create(host, {
  label: 'Department',
  levelLabels: ['Division', 'Department', 'Team'],
  options: [{ value: 'ops', label: 'Operations' }, { value: 'eng', label: 'Engineering' }],
  loadChildren: async (option, { signal, path }): Promise<CascaderOption[]> => {
    const response = await fetch(`/api/org/${path.map(encodeURIComponent).join('/')}`, { signal });
    if (!response.ok) throw new Error(`HTTP ${String(response.status)}`);
    const rows = (await response.json()) as { id: string; name: string; leaf: boolean }[];
    return rows.map((r) => ({ value: r.id, label: r.name, isLeaf: r.leaf || path.length >= 2 }));
  },
});

